CREATE TABLE IF NOT EXISTS venues_records(school_id TEXT NOT NULL,kind TEXT NOT NULL,record_id TEXT NOT NULL,revision INTEGER NOT NULL,service_date TEXT,venue_id TEXT,status TEXT,data_json TEXT NOT NULL,PRIMARY KEY(school_id,kind,record_id));
CREATE INDEX IF NOT EXISTS venues_records_date ON venues_records(school_id,kind,service_date,venue_id);
CREATE TABLE IF NOT EXISTS venues_intervals(school_id TEXT NOT NULL,record_id TEXT NOT NULL,kind TEXT NOT NULL,venue_id TEXT NOT NULL,overlap_group TEXT NOT NULL DEFAULT '',start_at INTEGER NOT NULL,end_at INTEGER NOT NULL,buffer_ms INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL,source_domain TEXT,source_revision TEXT,PRIMARY KEY(school_id,kind,record_id,start_at));
CREATE INDEX IF NOT EXISTS venues_intervals_overlap ON venues_intervals(school_id,venue_id,start_at,end_at,status);
CREATE INDEX IF NOT EXISTS venues_intervals_linked ON venues_intervals(school_id,overlap_group,start_at,end_at,status);
CREATE TABLE IF NOT EXISTS venues_source_fences(school_id TEXT NOT NULL,source_domain TEXT NOT NULL,source_operation_id TEXT NOT NULL,source_digest TEXT NOT NULL,source_fence INTEGER NOT NULL,decision_id TEXT NOT NULL,state TEXT NOT NULL,created_at INTEGER NOT NULL,resolved_at INTEGER,receipt_json TEXT,PRIMARY KEY(school_id,source_domain,source_operation_id));
CREATE TABLE IF NOT EXISTS venues_fence_scopes(school_id TEXT NOT NULL,source_domain TEXT NOT NULL,source_operation_id TEXT NOT NULL,venue_id TEXT NOT NULL,start_at INTEGER NOT NULL,end_at INTEGER NOT NULL,PRIMARY KEY(school_id,source_domain,source_operation_id,venue_id,start_at));
CREATE INDEX IF NOT EXISTS venues_fence_overlap ON venues_fence_scopes(school_id,venue_id,start_at,end_at);
CREATE TABLE IF NOT EXISTS venues_source_heads(school_id TEXT NOT NULL,source_domain TEXT NOT NULL,revision TEXT NOT NULL,sequence INTEGER NOT NULL,checked_at INTEGER NOT NULL,digest TEXT NOT NULL,metadata_json TEXT NOT NULL,PRIMARY KEY(school_id,source_domain));
CREATE TABLE IF NOT EXISTS venues_epochs(school_id TEXT NOT NULL,venue_id TEXT NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(school_id,venue_id));
CREATE TABLE IF NOT EXISTS venues_deliveries(school_id TEXT NOT NULL,notification_id TEXT NOT NULL,staff_id TEXT NOT NULL,channel TEXT NOT NULL,state TEXT NOT NULL,provider_id TEXT,reason_code TEXT,updated_at INTEGER NOT NULL,dispatch_fence INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(school_id,notification_id,staff_id,channel));
CREATE TABLE IF NOT EXISTS venues_projection_manifests(school_id TEXT NOT NULL,source_domain TEXT NOT NULL,source_operation_id TEXT NOT NULL,manifest_digest TEXT NOT NULL,manifest_json TEXT NOT NULL,chunk_count INTEGER NOT NULL,validated_count INTEGER NOT NULL DEFAULT 0,sealed INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(school_id,source_domain,source_operation_id));
CREATE TABLE IF NOT EXISTS venues_projection_parts(school_id TEXT NOT NULL,source_domain TEXT NOT NULL,source_operation_id TEXT NOT NULL,chunk_index INTEGER NOT NULL,digest TEXT NOT NULL,row_count INTEGER NOT NULL,PRIMARY KEY(school_id,source_domain,source_operation_id,chunk_index));
CREATE TABLE IF NOT EXISTS venues_projection_rows(school_id TEXT NOT NULL,source_domain TEXT NOT NULL,source_operation_id TEXT NOT NULL,row_key TEXT NOT NULL,source_id TEXT NOT NULL,venue_id TEXT NOT NULL,overlap_group TEXT NOT NULL,start_at INTEGER NOT NULL,end_at INTEGER NOT NULL,buffer_ms INTEGER NOT NULL,PRIMARY KEY(school_id,source_domain,source_operation_id,row_key));
CREATE INDEX IF NOT EXISTS venues_projection_overlap ON venues_projection_rows(school_id,venue_id,start_at,end_at);
CREATE VIEW IF NOT EXISTS venues_occupancy AS SELECT * FROM venues_intervals UNION ALL SELECT r.school_id,r.source_id AS record_id,'source' AS kind,r.venue_id,COALESCE(json_extract(v.data_json,'$.overlapGroup'),'') AS overlap_group,r.start_at,r.end_at,COALESCE(json_extract(v.data_json,'$.bufferMinutes'),0)*60000 AS buffer_ms,'active' AS status,h.source_domain,h.revision AS source_revision FROM venues_projection_rows r JOIN venues_source_heads h ON h.school_id=r.school_id AND json_extract(h.metadata_json,'$.sourceOperationId')=r.source_operation_id AND json_extract(h.metadata_json,'$.sourceDomain')=r.source_domain JOIN venues_records v ON v.school_id=r.school_id AND v.kind='venues' AND v.record_id=r.venue_id WHERE h.source_domain<>'roster:baseline' OR NOT EXISTS(SELECT 1 FROM venues_source_heads d WHERE d.school_id=r.school_id AND d.source_domain='roster:' || date(r.start_at/1000,'unixepoch','+8 hours'));
ALTER TABLE venues_deliveries ADD COLUMN provider_status TEXT;
ALTER TABLE venues_deliveries ADD COLUMN provider_occurred_at INTEGER;
ALTER TABLE venues_deliveries ADD COLUMN provider_event_id TEXT;
CREATE INDEX IF NOT EXISTS venues_delivery_provider ON venues_deliveries(school_id,channel,provider_id);
CREATE TABLE IF NOT EXISTS venues_notification_progress(school_id TEXT NOT NULL,notification_id TEXT NOT NULL,job_fence INTEGER NOT NULL,complete INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(school_id,notification_id));
CREATE TABLE IF NOT EXISTS venues_receipt_reconciliation(school_id TEXT NOT NULL,notification_id TEXT NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(school_id,notification_id));
